DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":1,"title":"المدرسة الإحيائية","passage":"تُدرس المدرسة الإحيائية في الشعر العربي الحديث بملاحظة استلهام البناء العمودي واللغة التراثية والأغراض القديمة مع حضور موضوعات العصر؛ لا يكفي الوزن وحده لتصنيف قصيدة. ينبغي مقارنة قصيدتين موثقتين وتحليل اختيار المطلع والصورة ووظيفة القافية.","question":"ما أقوى دليل على سمة إحيائية في قصيدة؟","correct":"تحليل بناء القصيدة ولغتها في سياقها","wrong":["الاعتماد على تاريخ الميلاد فقط","اسم البلد وحده","عدد الصفحات"],"practice":"قارن مطلعين لشاعرين موثقي المصدر وبيّن سمة استمرارية وأخرى متغيرة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":2,"title":"في سرنديب","passage":"يستلزم درس «في سرنديب» نص القصيدة المقرر وسيرة شاعرها المعتمدة قبل وصف المشهد أو زمن المنفى، ولا يجوز اختلاق أبيات أو تفصيل رحلته. في نموذج مستقل يرى مسافر جزيرة من بعيد ويقارن طبيعتها بذكريات وطنه؛ هذا نثر تدريبي لا جزء من القصيدة.","question":"ما الدليل الصحيح لفهم صورة الجزيرة في القصيدة؟","correct":"شاهد من النص الموثق وسياق المتكلم","wrong":["العنوان وحده","قصة غير محققة","شطر مبتكر"],"practice":"استخرج من النص الأصلي صورة مكانية وعاطفة مدعومتين بشاهد صحيح المصدر.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":3,"title":"بني سورية لأحمد شوقي","passage":"يتطلب تحليل «بني سورية» لأحمد شوقي الرجوع إلى الأبيات الصحيحة لمعرفة المخاطب والغرض والسياق، فلا تُؤلف له عبارات أو أحداث سياسية محددة. في مثال أصلي يدعو متحدث إلى التعاون وخدمة المجتمع دون أن يكرر القصيدة.","question":"ما الذي يحدد المخاطب في القصيدة؟","correct":"أساليب النداء والضمائر في الأبيات","wrong":["اللقب وحده","تخمين حادثة","اختلاق شطر"],"practice":"وثق أسلوب نداء من القصيدة وفسر وظيفته في صياغة الغرض.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":4,"title":"الفرات الطاغي للجواهري","passage":"لا يمكن وصف فيضان بعينه أو استنتاج مكان أحداث «الفرات الطاغي» للجواهري من العنوان وحده؛ يتطلب التحليل نص الشاعر الصحيح وسياقه. نموذج مستقل يراقب سكان نهرًا ارتفع منسوبه وينظمون إجراءات سلامة، وهو قصة حديثة لا شعر الجواهري.","question":"ما الذي يثبت معنى صورة النهر في النص الشعري؟","correct":"الأبيات الصحيحة وقرائن السياق","wrong":["أرقام مياه مختلقة","العنوان وحده","قصة مستقلة بديلة"],"practice":"حلل من النص الأصلي صورة طبيعية أو إنسانية موثقة واشرح أثرها الوجداني.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":5,"title":"سفارة الشعر لابن حامدن","passage":"تحتاج قصيدة «سفارة الشعر» لابن حامدن إلى مصدرها الموثق قبل تحديد ما ينسبه الشاعر إلى الشعر من رسالة. في تدريب مستقل يمثل طالب الشعر جسرًا للتفاهم بين قراء من بيئات متعددة؛ ليس بيتًا من القصيدة.","question":"ما الطريق الدقيق لمعرفة وظيفة الشعر عند صاحب القصيدة؟","correct":"التحليل من الأبيات الموثقة","wrong":["تخمين من عنوان الدرس","اختراع قول","اعتبار كل شاعر يوافق غيره"],"practice":"حدد عبارة صحيحة من القصيدة تتصل بدور الشعر ثم ناقش صورة فنية فيها.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":6,"title":"الرومانسية","passage":"قد يظهر الاتجاه الرومنسي في العناية بالذات والوجدان والطبيعة والخيال، لكن كل نص عن شجرة أو بحر ليس رومنسيًا بالضرورة. في مثال مستقل يصف متكلم الغروب بوصفه صورة لحنينه إلى صديق؛ التحليل يجمع العاطفة والتصوير والسياق.","question":"أي قرينة تدعم القراءة الرومنسية في المثال؟","correct":"ارتباط صورة الغروب بالعاطفة الذاتية","wrong":["ذكر مكان مجرد","قافية وحدها","عدد الأفعال"],"practice":"اختر نصًا رومنسيًا صحيح النسبة واستخرج عاطفة وصورة وطريقة بنائهما.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":7,"title":"المساء لخليل مطران","passage":"قصيدة «المساء» لخليل مطران تحتاج نصًا صحيحًا لتحديد أثر الطبيعة في الشعور وموقع التشبيه أو الاستعارة، ولا يجوز اختلاق أبيات عنه. مثال مستقل «كان البحر هادئًا بينما ازدحمت أفكار المسافر» يقدم تضادًا بين المشهد والنفس ولا يمثل القصيدة.","question":"ما الذي يفسر علاقة الطبيعة بعاطفة الشاعر؟","correct":"صور وألفاظ أصلية من الأبيات","wrong":["عنوان القصيدة فقط","بيت غير موجود","عدد حروف القافية"],"practice":"استخرج صورة طبيعية موثقة من «المساء» واشرح أثرها في تطور الانفعال.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":8,"title":"كن بلسما لأبي ماضي","passage":"يتطلب درس «كن بلسما» لإيليا أبي ماضي مراجعه الأبيات الصحيحة قبل تحديد الأساليب أو إضافة وصايا على لسانه. في موقف مستقل يساند متعلم زميلًا يواجه صعوبة، وهو مثال على العطف وليس نقلًا للشعر.","question":"ما الشرط لنسبة أسلوب أمر إلى الشاعر؟","correct":"وجوده نصًا في بيت موثق","wrong":["توليد جملة ملائمة","عنوان القصيدة فقط","نقل قول مجهول"],"practice":"حلل صيغة طلب موثقة في النص المقرر وعلاقتها بالقيمة الوجدانية.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":9,"title":"في ظل وادي الموت لأبي القاسم الشابي","passage":"يحتاج نص «في ظل وادي الموت» لأبي القاسم الشابي إلى أبياته المقررة قبل تقرير أن الوادي مكان جغرافي أو رمز فني. نموذج مستقل يصور راوٍ مكانًا مظلمًا يثير القلق ثم يجد مخرجًا؛ لا يعد من شعر الشابي.","question":"ما الذي يحدد كون «الوادي» رمزًا في القصيدة؟","correct":"قرائن الصور والسياق الشعري الصحيح","wrong":["اسم المكان وحده","قصيدة من إنشائنا","افتراض نية الشاعر"],"practice":"استخرج صورة شعرية حقيقية وناقش العلاقة بين المكان والحالة النفسية.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":10,"title":"الطاغية لفاضل أمين","passage":"لا يصح نسبة موقف سياسي أو حادثة أو بيت إلى مؤلف «الطاغية» دون النص الأدبي الموثق، ويجب التفريق بين شخصية متخيلة وحاكم تاريخي. في نص مستقل يقف فريق ضد قرار ظالم بطرق مؤسسية وسلمية ويقدم حججًا، ولا يمثل القصيدة.","question":"ما الذي يميز الاستنتاج النقدي الموثق عن التخمين؟","correct":"شاهد واضح من النص وسياقه","wrong":["العنوان وحده","رواية مختلقة","إسقاط حدث خارجي بلا دليل"],"practice":"حلل صورة أو موقفًا من النص الصحيح واشرح حدود الاستنتاج.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":11,"title":"الشعر العربي المعاصر (الشعر الحر)","passage":"يتنوع الشعر العربي المعاصر في بناء القصيدة والتفعيلة والإيقاع والصورة، وقد تختلف صيغة الشعر الحر عن القصيدة العمودية في تكرار التفعيلات وتوزيع الأسطر؛ لا يصح وصف كل نص بلا قافية بأنه على وزن التفعيلة.","question":"ما المنهج الأفضل لتمييز شعر التفعيلة؟","correct":"تحليل التفعيلة وتوزيع الأسطر والإيقاع","wrong":["غياب القافية وحده","عنوان معاصر فقط","طول البيت"],"practice":"قارن مقطعًا عموديًا ومقطع تفعيلة صحيحَي النسبة من حيث البناء والإيقاع.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":12,"title":"سربروس في بابل للسياب","passage":"تستلزم قراءة «سربروس في بابل» لبدر شاكر السياب فهم النص الحقيقي ودلالة استدعاء الشخصية الأسطورية ضمنه، ولا يجوز اختلاق رمز أو اقتباس من القصيدة. مثال مستقل يستعمل راو شخصية خيالية للتعبير عن خوف جمعي، وليس من النص.","question":"ما الذي يثبت وظيفة الرمز الأسطوري في القصيدة؟","correct":"مواضعه الفعلية والسياق والصور","wrong":["اسم الشخصية وحده","تفسير خارجي بلا شاهد","مقطع مولد"],"practice":"وثق من القصيدة إشارة أسطورية صحيحة وفسر علاقتها ببنية المعنى.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":13,"title":"سوسنة اسمها القدس","passage":"لا يحدد العنوان وحده مؤلف «سوسنة اسمها القدس» أو تفاصيل القصيدة وصورها؛ يحتاج المتعلم إلى النص المقرر الصحيح. في مثال مستقل تصير زهرة رمزًا للذاكرة ومكان عزيز؛ هذا تدريب على الرمز لا نص منسوب.","question":"ما الدليل على دلالة الزهرة الرمزية؟","correct":"سياق الصور والأبيات الموثقة","wrong":["لون مختلق","التخمين من العنوان","إلغاء صوت المتكلم"],"practice":"ابحث في النص الصحيح عن صورة واحدة للمدينة واشرح علاقتها بالمخاطب.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":14,"title":"هوامش على دفتر النكسة لنزار قباني","passage":"تحتاج قصيدة «هوامش على دفتر النكسة» لنزار قباني إلى نصها الموثق وسياقها التاريخي، مع التمييز بين النقد البلاغي والوقائع الخارجية. لا يعيد ضاديوم نشر أبيات القصيدة أو ينتج صياغات منسوبة إليه.","question":"ما الذي يجعل قراءة قصيدة ذات سياق سياسي متزنة؟","correct":"توثيق النص والتاريخ وتحليل الأسلوب","wrong":["نسبة نص مختلق","تعميم رأي الشاعر","الاعتماد على عنوان فقط"],"practice":"استخرج من نسخة مأذونة موضع سؤال أو نقد وفسر وظيفته دون تجاوز حدود الشاهد.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":15,"title":"المجد للإنسان لأحمدو عبد القادر","passage":"لا يُستنتج مضمون «المجد للإنسان» لأحمدو عبد القادر من العنوان وحده، بل تُقرأ الأبيات الموثقة لمعرفة صورة الإنسان في النص. مثال أصلي يصف فريقًا ينجز عملًا مشتركًا لصالح الآخرين، ولا يمثل قول الشاعر.","question":"ما الذي يحدد صورة الإنسان الفنية في القصيدة؟","correct":"ألفاظ وصور صحيحة من النص","wrong":["اسم الشاعر دون أبيات","خبر مجهول","اقتباس مخترع"],"practice":"حلل من النص المدرسي صورتين تتصلان بالإنسان مع تفسير أثرهما.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":16,"title":"الإيقاع الشعري","passage":"يتشكل الإيقاع الشعري من الوزن والقافية في مواضعها، ومن التكرار والتوازي والأصوات على مستويات أخرى؛ ولا تكفي قافية واحدة للحكم على وزن البيت أو جودته. يجب اعتماد النص المضبوط والتقطيع قبل تسمية البحر.","question":"ما الأداة الأدق لتحديد الوزن الخارجي؟","correct":"التقطيع العروضي للمقاطع","wrong":["عد كلمات العنوان","الموقف السياسي","اسم الشاعر"],"practice":"اختر أبياتًا موثقة وحلل عنصرًا خارجيًا وآخر داخليًا من إيقاعها.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":17,"title":"ظواهر الإيقاع الداخلي","passage":"قد يتولد الإيقاع الداخلي من تكرار لفظ أو صوت أو تركيب نحوي أو توازٍ معنوي يخدم الفكرة، ولا يساوي كل تكرار حشوًا. في نص مستقل «يعود السؤال، ويعود البحث، ويعود الأمل» يتكرر الفعل لتعزيز الاستمرار.","question":"ما العنصر الذي صنع التوازي في المثال؟","correct":"تكرار الفعل «يعود»","wrong":["وزن البحر الكامل","أداة شرط","قافية نثرية لازمة"],"practice":"حدد تكرارًا وتوازيًا في نص مأذون وناقش وظيفتهما.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":18,"title":"بحر الهزج","passage":"من الصور الشائعة لمجزوء الهزج «مفاعيلن مفاعيلن» في كل شطر، وتدخل عليه تغييرات عروضية تحتاج مراجعة مرجع موثوق. يعتمد التقطيع على الأصوات المنطوقة لا ترتيب الكلمات.","question":"ما التفعيلة الأساسية لبحر الهزج؟","correct":"مفاعيلن","wrong":["متفاعلن","فاعلاتن","مستفعلن"],"practice":"قطّع بيتًا موثقًا على بحر الهزج مع بيان صورته المستعملة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":19,"title":"المتدارك أو الخبب","passage":"تحتاج دراسة المتدارك والخبب إلى تمييز الصيغ الإيقاعية والتفاعيل المستعملة واختلاف الوصف العروضي في المراجع؛ من أصول المتدارك تكرار «فاعلن»، بينما للخبب معالجة إيقاعية تتطلب شرحًا خاصًا، ولا يصح اعتباره مرادفًا تامًا دون توضيح.","question":"ما التفعيلة المرتبطة بأصل وزن المتدارك؟","correct":"فاعلن","wrong":["مفاعلتن","متفاعلن","مفعولات"],"practice":"راجع بيتين موثقين، أحدهما على المتدارك وآخر في نسق الخبب، وقارن التحليل المقدم في مرجع عروض.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":20,"title":"بحر السريع","passage":"في صورته التامة الشائعة يقوم بحر السريع في كل شطر على «مستفعلن مستفعلن مفعولاتُ» قبل ما يطرأ من تغييرات عروضية، وغالبًا تظهر صور مختلفة للضرب والعروض؛ لا يجوز تخمين الوزن من عدد الكلمات.","question":"ما التفعيلة التي تبدأ بها صورة السريع المذكورة؟","correct":"مستفعلن","wrong":["فاعلاتن","فعولن","متفاعلن"],"practice":"اختر بيتًا على السريع من مرجع موثوق وقطّعه مع توضيح التغيير العروضي.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":21,"title":"السطر والمقطع الشعريان","passage":"في شعر التفعيلة قد تتوزع الجملة الإيقاعية على أسطر متفاوتة الطول، وقد يجمع المقطع مجموعة أسطر ترتبط بصورة أو فكرة؛ لكن تقسيم السطور لا يثبت وحده وجود وزن. تقرأ البنية مع الحركة الدلالية والإيقاع.","question":"ما الفرق بين السطر والمقطع في تحليل القصيدة؟","correct":"المقطع قد يجمع أسطرًا مرتبطة بمعنى أو إيقاع","wrong":["كل مقطع كلمة واحدة","السطر لا يحتوي فعلًا","المقطع يعني قافية فقط"],"practice":"حلل ترتيب أسطر مقطع شعري مأذون مع ملاحظة الانتقال بين الصور.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":22,"title":"الصورة الشعرية ومكوناتها","passage":"تتكون الصورة الشعرية من اختيار الألفاظ والعلاقات التخيلية والحواس والسياق العاطفي؛ قد يتضمن التشبيه أو الاستعارة أو الكناية. في نموذج مستقل «تتثاءب الطرق عند الفجر» صورة تشخص الطرق دون أن تكون وصفًا علميًا.","question":"ما الصورة في «تتثاءب الطرق»؟","correct":"تشخيص مجازي للطرق","wrong":["حقيقة علمية","مفعول مطلق","أسلوب شرط"],"practice":"أنشئ صورة من ثلاث حواس واشرح كيف تدعم عاطفة أو معنى مركزيًا.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":23,"title":"مهارة كتابة مقال تحليلي لنص شعري","passage":"يحتاج المقال التحليلي إلى أطروحة تعلن القضية، ثم شاهد صحيح من النص وتفسير صورته وإيقاعه وعلاقته بالغرض، وخاتمة لا تتجاوز الأدلة. لا يعد تكرار عنوان القصيدة تحليلًا ولا يصح نسبة شطر مختلق لمؤلف.","question":"ما العنصر الأساسي في فقرة تحليل قصيدة؟","correct":"شاهد صحيح مع تفسير أثره","wrong":["رأي بلا دليل","اقتباس مولد","عدد الصفحات"],"practice":"اكتب ثلاث فقرات عن قصيدة موثقة: فكرة، وشاهدين وتحليل، وخاتمة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"},{"cid":"9dccf559-931a-4f7b-b2b8-96216ec9fa62","unit":"3e7c8f0a-55c9-4f50-a588-9bb9b4585583","n":24,"title":"تجميع المعطيات - دراسة الخصائص الفنية","passage":"تجمع دراسة الخصائص الفنية معلومات النص من لغته وصوره وبنائه وإيقاعه ضمن جدول واحد، ثم تفصل الملاحظات من الاستنتاجات. في نص مستقل تقارن طالبة صورتين وسبب ترتيب الجمل قبل الحكم على الأثر.","question":"ما الخطوة التي تسبق الاستنتاج النقدي الموثق؟","correct":"جمع شواهد من اللغة والبناء والصورة","wrong":["إعلان النتيجة أولًا","إلغاء السياق","اختيار رأي شائع"],"practice":"أعد بطاقة نقدية لنص شعري صحيح المصدر تتضمن أربعة معايير وأدلة مستقلة.","old":"DADYOOM_MR_G13_LITERARY_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=13 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G13_POETRY_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G13_POETRY_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G13_POETRY_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G13_POETRY_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_ARTS_POETRY_ORIGINAL_24_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_ARTS_POETRY_ORIGINAL_24_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G13_ARTS_POETRY_ORIGINAL_24_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G13_ARTS_POETRY_ORIGINAL_24_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G13_POETRY_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;